<?php
namespace App\Console\Commands;
use App\Mail\SavingsOffersReportMail; use App\Models\User; use App\Services\NotificationService; use App\Services\SavingsOffersReportService; use Carbon\CarbonImmutable; use Illuminate\Console\Command;
class EmailSavingsOffersReports extends Command { protected $signature='savings-offers-reports:email {--from=} {--to=} {--user=}'; protected $description='Email savings offers based on recent spending'; public function handle(SavingsOffersReportService $reports, NotificationService $mail): int { if (! config('services.offers.enabled')) { $this->info('Savings Offers reports are disabled by SAVINGS_OFFERS_ENABLED.'); return self::SUCCESS; } $to=CarbonImmutable::parse($this->option('to') ?: now())->endOfDay(); $from=CarbonImmutable::parse($this->option('from') ?: $to->startOfMonth())->startOfDay(); $users=User::query()->select(['id','name','email']); if($this->option('user')) $users->whereKey((int)$this->option('user')); foreach($users->get() as $user){ $report=$reports->generate($user,$from,$to); $mail->sendEmail($user->email,new SavingsOffersReportMail($report['advice'],$report['pdf'],$report['filename'])); $this->info("Sent savings offers to user {$user->id}"); } return self::SUCCESS; } }
